from pathlib import Path
import json,hashlib,sys,csv
import numpy as np,pandas as pd
B=Path(__file__).resolve().parent;I=B.parents[2];sys.path.insert(0,str(I/'src'))
from ptquat.data import load_tidy_sparc

if (B/'PREDECLARED_DESIGN.json').exists():raise FileExistsError('Refuse to overwrite frozen gate authority/design')
def js(p,x):p.write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n')
gd=load_tidy_sparc(str(I/'dataset/sparc_tidy.csv'));rows=[]
for name,g in sorted(gd.items()):
 ok=(g.r_kpc>0)&(g.v_obs>0);slope=float(np.polyfit(np.log(g.r_kpc[ok]),np.log(g.v_obs[ok]),1)[0]) if sum(ok)>=3 else 0.
 rows.append(dict(galaxy=name,i_deg=g.i_deg,relD=g.D_err_Mpc/g.D_Mpc,i_err_deg=g.i_err_deg,inc_fraction=float(np.radians(g.i_err_deg)/np.tan(np.radians(g.i_deg))),n=len(g.r_kpc),observed_log_slope=slope,abs_slope=abs(slope)))
selected=[]
for rule,key,sign in [('lowest inclination','i_deg',1),('largest fractional distance uncertainty','relD',-1),('largest linear inclination fraction','inc_fraction',-1),('smallest point count','n',1),('largest point count','n',-1),('largest absolute observed log slope','abs_slope',-1)]:
 pool=[x for x in rows if x['galaxy'] not in [y['galaxy'] for y in selected]];s=sorted(pool,key=lambda x:(sign*x[key],x['galaxy']))[0].copy();s['selection_rule']=rule;selected.append(s)
# Validate frozen tidy values against raw columns without modifying data or rerunning ETL.
t=pd.read_csv(I/'dataset/sparc_tidy.csv');r=pd.read_csv(I/'dataset/raw/vizier_table2.csv');j=t.merge(r,left_on=['galaxy','r_kpc'],right_on=['Name','Rad'],validate='one_to_one');checks={}
for a,b in [('v_obs_kms','Vobs'),('v_err_kms','e_Vobs'),('v_disk_kms','Vdisk'),('v_bulge_kms','Vbulge'),('v_gas_kms','Vgas'),('D_Mpc','Dist')]: checks[a]=float(abs(j[a]-j[b]).max())
js(B/'RAW_TIDY_LINK.json',dict(rows=len(j),all_nominal_columns_max_abs_delta=checks))
with (B/'selection_population.csv').open('w') as f:
 w=csv.DictWriter(f,fieldnames=rows[0]);w.writeheader();w.writerows(rows)
contract=dict(source='Li et al 2018 arXiv:1803.00022v2 sec2.1 Eqs4,5; SPARC Table2 definitions',radius='r(D)=r0 D/D0 at fixed angular sample',templates='v_k(D)=v_k0 sqrt(D/D0) for disk,bulge,gas; fixed angular shape; Upsilon held fixed',observations='y(i)=y0 sin(i0)/sin(i); e(i)=e0 sin(i0)/sin(i)',template_inclination='standard catalog-level transform keeps templates fixed under global i; rephotometry/warped-disk geometry not recoverable',residual='r_trans=y(i)-vm(D); JD=-dvm/dD; Ji=-y0 cot(i0) per rad',fixed_frame_residual='r_nom=y0-vm(D) sin(i)/sin(i0); JD=-dvm/dD; Ji=-vm0 cot(i0) per rad',dist_cross_covariance='D/i independent; correlation unknown, set zero only as declared sensitivity assumption',sigma_sys='B0 nominal-frame additive floor; B1 intrinsic deprojected floor projected with sin(i)/sin(i0); neither choice claimed original documented nuisance generative law',data_dependent_vs_model_jacobian='propagating transformed observations uses y; marginalizing a fixed-data mean uses vm. Distinguish; signs kept in output.')
js(B/'OBSERVATION_CONTRACT.json',contract)
design=dict(schema_version=1,stage='FROZEN_BEFORE_NUMERICAL_MODEL_COMPARISONS',selected=selected,selection_uses='data geometry, uncertainties, point count, observed slope only; no residuals',models=['baryon','mond','ptq','ptq-nu','ptq-screen','mond-screen','nfw1p'],vectors='recovered original binary MLE; SHA256 in INPUT_AUTHORITY.json',synthetic=[dict(name='synthetic_flat',beta=0.,i_deg=35),dict(name='synthetic_rising',beta=0.5,i_deg=60),dict(name='synthetic_falling',beta=-0.25,i_deg=85)],synthetic_model='baryon only, n=8, D0=10, sigmaD=1, sigmai=3deg, U=1, sigma_sys=3, r=linspace(1,8),vd=80*r**beta,y=vd+3,e=2',fd_relative_steps=[1e-3,1e-4,1e-5],fd_inclination_step='relative step * max(i0 radians,0.5)',analytic_reference='nonhalo dvm/dD=vm/(2D); NFW analytic halo radial derivative plus baryon amplitude; Ji=-y cot for transformed residual; -vm cot for fixed frame',tolerances=dict(fd_absolute_kms_per_unit=1e-5,fd_relative_norm=1e-6,likelihood_abs=1e-8,covariance_relative_frobenius=1e-9,mapped_identity_abs=1e-7,quadrature_logL_medium_high=1e-3),materiality_flags=dict(abs_delta_logL=1.,relative_covariance_frobenius=0.01,interpretation='diagnostic flags, not universal scientific validity thresholds; no post-refit prediction'),parameter_points=['original','scale*1.01 where available','q*1.01 where available','selected U +0.01 if within bounds else -0.01','sigma_sys*1.01'],callback_design='static source call trace plus execute source AST nested optimizer callbacks with prescribed inputs only; no optimizer driver or optimize routine is called',nuisance_galaxies=[x['galaxy'] for x in selected[:3]],quadrature_orders=[16,32,64,128],quadrature_bounds='independent normalized Gaussian weights on zD,zi within +/-3, truncated D>0 and 0<i<90deg; no cos(i) prior; Gauss-Legendre products',conditional='fixed nominal y0; mu=vm(D)*sin(i)/sin(i0); diag e0^2+sigma_sys^2 (B0), diag e0^2+(sigma_sys*sin(i)/sin(i0))^2 (B1); no propagated terms',linear_references=['A production','A_Donly replaces JD with full distance derivative, retains model inclination','A_full_transformed uses full residual y-based Ji','A_fixed_frame uses full distance and model-based Ji'],budget='6 real galaxies *7 models;3 synthetic baryon controls;3 nuisance galaxies *7 models*2 floor conventions*4 orders <= 1e6 node-model evaluations; time limit 15min; no extra adaptive cases',stop_rules=['retain all nonconvergence and exceptions','no higher grid beyond128','if convention unsupported mark affected test BLOCKED_BY_CONVENTION; run only explicit conditional source-backed catalog transform','no refit or production changes even after failure'])
js(B/'PREDECLARED_DESIGN.json',design)
print(json.dumps(selected,indent=2));print('design SHA256',hashlib.sha256((B/'PREDECLARED_DESIGN.json').read_bytes()).hexdigest())
